// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address target, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        if (target == address(0)) target = address(1);

        vm.deal(address(this), amount);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint256 before = address(c).balance;
        vm.prank(address(this));
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}
